def wydaj(stan, ilosc):
    """Zwraca nowy stan po wydaniu towaru; zła ilość → ValueError."""
    if ilosc <= 0:
        raise ValueError("ilość musi być dodatnia")
    if ilosc > stan:
        raise ValueError(f"brak towaru: na stanie {stan}")
    return stan - ilosc


