def srednia_ceny(ceny):
    suma = 0
    for i in range(1, len(ceny)):
        suma += ceny[i]
    return suma / len(ceny)


def srednia_ceny_poprawiona(ceny):
    if not ceny:
        return 0
    suma = 0
    for cena in ceny:
        suma += cena
    return suma / len(ceny)


