def czy_ilosc_poprawna(ilosc):
    """Wymaganie: ilość w zamówieniu to liczba całkowita od 1 do 50."""
    return isinstance(ilosc, int) and 1 <= ilosc <= 50


def czy_ilosc_z_defektem(ilosc):
    return isinstance(ilosc, int) and 1 <= ilosc < 50


